def exercised_flag_to_exercises(apps, schema_editor):
    """A grant marked "ya ejercidas" becomes one exercise of all its options (date and FMV as best known)."""
    EquityGrant = apps.get_model("portfolio", "EquityGrant")
    EquityExercise = apps.get_model("portfolio", "EquityExercise")
    for g in EquityGrant.objects.filter(exercised=True).exclude(grant_type="shares"):
        EquityExercise.objects.create(
            grant=g, date=g.grant_date or g.vesting_start or dt.date.today(), quantity=g.quantity, fmv=g.fmv,
            notes="Marcado como ejercido antes de registrar ejercicios parciales.",
        )


